"""
Synchronous fact extraction pipeline for Cognis.

Replaces the production Lambda/SQS async pipeline with in-process extraction.
Uses Sonorus's configured LLM provider for LLM calls.

Pipeline:
1. Get unprocessed messages
2. Extract facts via LLM (USER_MEMORY_EXTRACTION_PROMPT)
3. Find similar existing memories via vector search
4. Decide operations via LLM: ADD/UPDATE/DELETE/NONE
5. Process operations (store new, mark old as historical)
6. Mark messages as processed
"""

import json
import re
import logging
import os
import calendar
from datetime import datetime, timezone
from typing import List, Dict, Any, Optional

import llm
from cognis.config import CognisConfig
from cognis.models import Memory, MemoryMetadata
from cognis.stores.sqlite_store import SQLiteStore
from cognis.stores.qdrant_store import QdrantLocalStore
from cognis.embeddings.base import BaseEmbedder
from cognis.extraction.prompts import (
    UPDATE_MEMORY_SYSTEM_PROMPT,
    UPDATE_MEMORY_USER_PROMPT,
    USER_MEMORY_EXTRACTION_PROMPT,
)
from cognis.utils import generate_memory_id, now_utc

logger = logging.getLogger(__name__)


def _next_month_datetime(value: datetime) -> datetime:
    year = value.year + 1 if value.month == 12 else value.year
    month = 1 if value.month == 12 else value.month + 1
    day = min(value.day, calendar.monthrange(year, month)[1])
    return value.replace(year=year, month=month, day=day)


class SyncFactExtractor:
    """Synchronous fact extraction via the Sonorus LLM router."""

    def __init__(
        self,
        sqlite_store: SQLiteStore,
        qdrant_store: QdrantLocalStore,
        embedder: BaseEmbedder,
        config: CognisConfig,
        api_key: Optional[str] = None,
    ):
        self._sqlite = sqlite_store
        self._qdrant = qdrant_store
        self._embedder = embedder
        self._config = config

    def extract_and_store(
        self,
        owner_id: str,
        session_id: Optional[str] = None,
        agent_id: Optional[str] = None,
        messages: Optional[List[Dict[str, str]]] = None,
        event_time: Optional[datetime] = None,
    ) -> List[Memory]:
        """
        Extract facts from messages and store them.

        Args:
            owner_id: Memory owner
            session_id: Current session
            agent_id: Current agent
            messages: Raw messages (if None, reads unprocessed from SQLite)

        Returns:
            List of newly created Memory objects
        """
        # Get messages
        if messages is None and session_id:
            raw = self._sqlite.get_unprocessed_messages(session_id, owner_id)
            messages = [{"role": m.get("role", "user"), "content": m.get("content", "")} for m in raw]

        if not messages:
            return []

        # Format messages for extraction
        parts = []
        for m in messages:
            role = m.get("role", "user")
            content = m.get("content", "")
            if not content.strip():
                continue
            if role == "user":
                parts.append(f"[USER] {content}")
            else:
                parts.append(f"[ASSISTANT] {content}")
        user_content = "\n".join(parts)

        if not user_content.strip():
            if session_id:
                self._sqlite.mark_messages_processed(session_id)
            return []

        # Step 1: Extract durable facts via LLM
        extracted_facts = self._extract_facts(user_content)
        if not extracted_facts:
            if session_id:
                self._sqlite.mark_messages_processed(session_id)
            return []
        facts = [item["fact"] for item in extracted_facts]
        category_by_fact = {
            self._normalize_fact_key(item["fact"]): item["category"]
            for item in extracted_facts
            if item.get("fact") and item.get("category") in self._config.categories
        }

        # Step 2: Find similar existing memories
        similar = self._find_similar_memories(user_content, owner_id, agent_id)

        # Step 3: Decide operations (ADD/UPDATE/DELETE/NONE)
        operations = self._decide_operations(facts, similar)

        # Step 4: Process operations
        new_memories = []
        for op in operations:
            event = op.get("event", "").upper()
            text = op.get("text", "")
            op_id = op.get("id", "new")
            category = category_by_fact.get(self._normalize_fact_key(text))

            if event == "ADD" and text.strip():
                memory = self._create_and_store(
                    text, owner_id, session_id, agent_id,
                    category=category, event_time=event_time,
                )
                if memory:
                    new_memories.append(memory)

            elif event == "UPDATE" and text.strip() and op_id != "new":
                # Mark old as historical
                self._sqlite.mark_historical(op_id, owner_id)
                self._qdrant.update_payload(op_id, {"is_current": False, "status": "historical"})
                # Get old version number
                old = self._sqlite.get_memory(op_id, owner_id)
                version = (old.version + 1) if old else 1
                memory = self._create_and_store(
                    text, owner_id, session_id, agent_id,
                    replaces_id=op_id, version=version,
                    category=category, event_time=event_time,
                )
                if memory:
                    new_memories.append(memory)

            elif event == "DELETE" and op_id != "new":
                self._sqlite.mark_historical(op_id, owner_id)
                self._qdrant.update_payload(op_id, {"is_current": False, "status": "historical"})

        # Step 5: Mark messages as processed
        if session_id:
            self._sqlite.mark_messages_processed(session_id)

        logger.info("Extracted %d new memories from %d messages", len(new_memories), len(messages))
        return new_memories

    def _llm_call(
        self,
        prompt: str,
        model: str,
        context: str,
        system_prompt: Optional[str] = None,
    ) -> str:
        """Make an LLM call through Sonorus's provider-aware router."""
        messages = []
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})
        messages.append({"role": "user", "content": prompt})
        response = llm.chat(
            messages=messages,
            model=model,
            temperature=0.0,
            max_tokens=4096,
            context=context,
        )
        if response is None:
            get_last_error = getattr(llm, "get_last_error", None)
            detail = get_last_error() if callable(get_last_error) else None
            raise RuntimeError(detail or f"LLM request failed for context '{context}'")
        text = response.strip()
        if not text:
            raise RuntimeError(f"LLM returned an empty response for context '{context}'")
        return text

    def _extract_facts(self, content: str) -> List[Dict[str, str]]:
        """Call LLM to extract facts from content."""
        now = datetime.now(timezone.utc)
        next_month = _next_month_datetime(now)

        prompt = USER_MEMORY_EXTRACTION_PROMPT.format(
            current_date=now.strftime("%Y-%m-%d"),
            user_message=content,
            next_month=next_month.strftime("%B %Y"),
        )

        try:
            text = self._llm_call(
                prompt,
                model=self._config.extraction_llm_model or self._config.llm_model,
                context="graphiti",
            )
            return self._parse_facts_json(text, strict=True)
        except Exception as e:
            logger.warning("Fact extraction failed: %s", e)
            raise

    def _find_similar_memories(
        self,
        content: str,
        owner_id: str,
        agent_id: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        """Find top-K similar existing memories for dedup/update decisions."""
        try:
            emb = self._embedder.embed_query(content)
            emb_small = emb.get(self._config.embedding_small_dim)
            if not emb_small:
                raise RuntimeError("Embedding provider returned no small query vector")

            results = self._qdrant.search(
                query_vector=emb_small,
                owner_id=owner_id,
                collection=self._qdrant.collection_small,
                agent_id=agent_id,
                limit=self._config.unified_operation_top_k,
                embedding_model=self._config.embedding_model,
            )
            return [
                {"id": mem.memory_id, "text": mem.content, "score": score}
                for mem, score in results
            ]
        except Exception as e:
            logger.warning("Similar memory search failed: %s", e)
            raise

    def _decide_operations(
        self,
        facts: List[str],
        similar: List[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        """Call LLM to decide ADD/UPDATE/DELETE/NONE for each fact."""
        if not similar:
            # No existing memories — all facts are ADDs
            return [{"id": "new", "text": f, "event": "ADD"} for f in facts]

        existing_str = json.dumps(
            [{"id": s["id"], "text": s["text"]} for s in similar],
            indent=2,
        )
        facts_str = json.dumps(facts)

        prompt = UPDATE_MEMORY_USER_PROMPT.format(
            existing_memory=existing_str,
            new_facts=facts_str,
        )

        try:
            text = self._llm_call(
                prompt,
                model=self._config.operation_llm_model or self._config.llm_model,
                context="graphiti_small",
                system_prompt=UPDATE_MEMORY_SYSTEM_PROMPT,
            )
            operations = self._parse_operations_json(text, strict=True)
            if not operations:
                raise ValueError("Deduplication response contained no memory operations")
            return operations
        except Exception as e:
            logger.warning("Operation decision failed: %s", e)
            raise

    def _categorize_fact(self, fact: str) -> str:
        """Best-effort fallback categorization for legacy string fact responses."""
        fact_lower = fact.lower()

        rules = [
            ("lore", ["inherited", "grandfather", "grandmother", "father", "mother", "family", "childhood", "secret", "background", "history"]),
            ("relationship", ["friend", "trusted", "distrusted", "argued", "promised", "betrayed", "debt", "loyal", "alliance"]),
            ("preference", ["likes", "dislikes", "prefers", "favorite", "hates", "enjoys", "values", "fears"]),
            ("milestone", ["remembered", "celebrated", "shared", "resolved", "completed", "memorable", "pleasant"]),
        ]

        for category, keywords in rules:
            if any(kw in fact_lower for kw in keywords):
                return category
        return ""

    @staticmethod
    def _normalize_fact_key(fact: str) -> str:
        return re.sub(r"\s+", " ", (fact or "").strip().lower())

    def _create_and_store(
        self,
        content: str,
        owner_id: str,
        session_id: Optional[str],
        agent_id: Optional[str],
        replaces_id: Optional[str] = None,
        version: int = 1,
        category: Optional[str] = None,
        event_time: Optional[datetime] = None,
    ) -> Optional[Memory]:
        """Create a Memory, embed it, and store in both SQLite and Qdrant."""
        try:
            category = category if category in self._config.categories else self._categorize_fact(content)
            if category not in self._config.categories:
                logger.info("Skipping unsupported memory fact category: %s", content)
                return None

            emb_result = self._embedder.embed_document(content)
            emb_full = emb_result.get(self._config.embedding_full_dim)
            emb_small = emb_result.get(self._config.embedding_small_dim)
            if not emb_full or not emb_small:
                raise RuntimeError("Embedding provider returned incomplete document vectors")

            memory = Memory(
                memory_id=generate_memory_id(),
                content=content,
                owner_id=owner_id,
                agent_id=agent_id,
                session_id=session_id,
                replaces_id=replaces_id,
                version=version,
                event_time=event_time,
                embedding_model=self._config.embedding_model,
                metadata=MemoryMetadata(category=category, scope="user"),
            )

            self._sqlite.store_memory(memory)
            self._qdrant.upsert(memory, emb_full, emb_small)
            return memory

        except Exception as e:
            logger.warning("Failed to create memory: %s", e)
            raise

    @staticmethod
    def _parse_facts_json(text: str, strict: bool = False) -> List[Dict[str, str]]:
        """Parse LLM response for facts list."""
        def normalize_facts(items: Any) -> List[Dict[str, str]]:
            facts: List[Dict[str, str]] = []
            if not isinstance(items, list):
                return facts
            for item in items:
                if isinstance(item, str) and item.strip():
                    facts.append({"category": "", "fact": item.strip()})
                elif isinstance(item, dict):
                    fact = str(item.get("fact") or item.get("text") or "").strip()
                    category = str(item.get("category") or item.get("type") or "").strip().lower()
                    if fact:
                        facts.append({"category": category, "fact": fact})
            return facts

        text = (text or "").strip()
        if not text:
            return []

        candidates = []
        final_match = re.search(r'(?:^|\n)\s*FINAL_JSON\s*:\s*(.*)$', text, re.IGNORECASE | re.DOTALL)
        if final_match:
            candidates.append(final_match.group(1).strip())
        else:
            candidates.append(text)

        decoder = json.JSONDecoder()
        for candidate in candidates:
            fenced_blocks = re.findall(r'```(?:json)?\s*(.*?)\s*```', candidate, re.IGNORECASE | re.DOTALL)
            chunks = list(reversed(fenced_blocks)) + [candidate]

            for chunk in chunks:
                chunk = chunk.strip()
                try:
                    data = json.loads(chunk)
                    if isinstance(data, dict) and isinstance(data.get("facts"), list):
                        return normalize_facts(data["facts"])
                except json.JSONDecodeError:
                    pass

                for object_start in (match.start() for match in re.finditer(r'\{', chunk)):
                    try:
                        data, _end = decoder.raw_decode(chunk[object_start:])
                    except json.JSONDecodeError:
                        continue
                    if isinstance(data, dict) and isinstance(data.get("facts"), list):
                        return normalize_facts(data["facts"])

        if strict:
            raise ValueError("Response did not contain a valid facts JSON payload")
        return []

    @staticmethod
    def _parse_operations_json(text: str, strict: bool = False) -> List[Dict[str, Any]]:
        """Parse LLM response for memory operations."""
        text = (text or "").strip()
        if not text:
            return []

        fenced_blocks = re.findall(r'```(?:json)?\s*(.*?)\s*```', text, re.IGNORECASE | re.DOTALL)
        chunks = list(reversed(fenced_blocks)) + [text]
        decoder = json.JSONDecoder()

        for chunk in chunks:
            chunk = chunk.strip()
            try:
                data = json.loads(chunk)
                if isinstance(data, dict) and isinstance(data.get("memory"), list):
                    return [op for op in data["memory"] if isinstance(op, dict)]
            except json.JSONDecodeError:
                pass

            for object_start in (match.start() for match in re.finditer(r'\{', chunk)):
                try:
                    data, _end = decoder.raw_decode(chunk[object_start:])
                except json.JSONDecodeError:
                    continue
                if isinstance(data, dict) and isinstance(data.get("memory"), list):
                    return [op for op in data["memory"] if isinstance(op, dict)]

        if strict:
            raise ValueError("Response did not contain a valid memory operations JSON payload")
        return []
